import type { PricingTier } from '@gntik-ai/blocks';
import { Check, Minus } from '@gntik-ai/icons';
import { Table, TableBody, TableCaption, TableCell, TableHead, TableHeader, TableRow } from '@gntik-ai/ui';
import { Fragment } from 'react';
import type { ComparisonSection, ComparisonValue } from './data';

function Value({ value }: { value: ComparisonValue | undefined }) {
  if (value === true)
    return (
      <>
        <Check size={16} aria-hidden className="inline text-primary-text" />
        <span className="sr-only">Included</span>
      </>
    );
  if (value === false || value === undefined)
    return (
      <>
        <Minus size={16} aria-hidden className="inline text-muted-foreground" />
        <span className="sr-only">Not included</span>
      </>
    );
  return <span className="text-foreground">{value}</span>;
}

/** Plan comparison: one column per tier, rows grouped by section (column-group headers). */
export function ComparisonTable({ tiers, sections, caption }: { tiers: readonly PricingTier[]; sections: readonly ComparisonSection[]; caption: string }) {
  return (
    <Table containerLabel={caption}>
      <TableCaption srOnly>{caption}</TableCaption>
      <TableHeader>
        <TableRow>
          <TableHead scope="col" className="w-[34%]">
            Feature
          </TableHead>
          {tiers.map((t) => (
            <TableHead key={t.id} scope="col" align="center">
              {t.name}
            </TableHead>
          ))}
        </TableRow>
      </TableHeader>
      <TableBody>
        {sections.map((s) => (
          <Fragment key={s.title}>
            <TableRow>
              <TableHead scope="colgroup" colSpan={tiers.length + 1} className="bg-secondary/40 text-foreground">
                {s.title}
              </TableHead>
            </TableRow>
            {s.rows.map((r) => (
              <TableRow key={r.feature}>
                <TableHead scope="row" className="font-normal text-foreground">
                  {r.feature}
                </TableHead>
                {tiers.map((t) => (
                  <TableCell key={t.id} align="center">
                    <Value value={r.values[t.id]} />
                  </TableCell>
                ))}
              </TableRow>
            ))}
          </Fragment>
        ))}
      </TableBody>
    </Table>
  );
}

import { Faq, FeatureGrid, PricingTable, samplePricingTiers, type FaqItem, type Feature, type PricingCycle, type PricingTier } from '@gntik-ai/blocks';
import { Section, Stack, type MegaMenuItem } from '@gntik-ai/ui';
import type { ReactNode } from 'react';
import { ComparisonTable } from './ComparisonTable';
import { comparisonSections, publicCopyright, publicFooterLinks, publicMenu, type ComparisonSection } from './data';
import { PublicFrame } from './PublicFrame';

export interface PricingProps {
  brand: ReactNode;
  /** MegaMenu items (MobileNav below lg). */
  menu: MegaMenuItem[];
  currentHref: string;
  signInHref: string;
  getStartedHref: string;
  title: ReactNode;
  description: ReactNode;
  tiers: PricingTier[];
  defaultCycle: PricingCycle;
  onSelectTier: (tier: PricingTier, cycle: PricingCycle) => void;
  /** Highlights above the comparison (FeatureGrid); omitted = block samples. */
  features: Feature[];
  comparison: ComparisonSection[];
  faqs: FaqItem[];
  footerLinks: Array<{ label: string; href: string }>;
  copyright: ReactNode;
}

/** Public pricing: StackedLayout + MegaMenu, PricingTable, FeatureGrid, plan comparison table and Faq. */
export default function PricingPage(props: Partial<PricingProps>) {
  const {
    brand,
    menu = publicMenu,
    currentHref = '/pricing',
    signInHref,
    getStartedHref,
    title = 'Simple pricing that grows with you',
    description = 'Start free, upgrade when your team does. Every paid plan has a 14-day trial.',
    tiers = samplePricingTiers,
    defaultCycle,
    onSelectTier,
    features,
    comparison = comparisonSections,
    faqs,
    footerLinks = publicFooterLinks,
    copyright = publicCopyright,
  } = props;
  return (
    <PublicFrame
      brand={brand}
      menu={menu}
      currentHref={currentHref}
      signInHref={signInHref}
      getStartedHref={getStartedHref}
      footerLinks={footerLinks}
      copyright={copyright}
    >
      <Stack gap={12}>
        <PricingTable eyebrow="Pricing" title={title} description={description} tiers={tiers} defaultCycle={defaultCycle} onSelectTier={onSelectTier} />
        <FeatureGrid eyebrow="Every plan" title="Included from day one" features={features} columns={3} />
        <Section title="Compare plans" description="Limits and features side by side.">
          <ComparisonTable tiers={tiers} sections={comparison} caption="Plan comparison" />
        </Section>
        <Faq items={faqs} layout="split" />
      </Stack>
    </PublicFrame>
  );
}

import { Button, Link, Logo, MegaMenu, MobileNav, StackedLayout, ThemeSwitcher, megaMenuNavItems, type MegaMenuItem } from '@gntik-ai/ui';
import type { ReactNode } from 'react';

export interface PublicFrameProps {
  brand?: ReactNode;
  menu: MegaMenuItem[];
  currentHref?: string;
  signInHref?: string;
  getStartedHref?: string;
  footerLinks: Array<{ label: string; href: string }>;
  copyright: ReactNode;
  children: ReactNode;
}

/**
 * Public-site chrome: StackedLayout with the MegaMenu as the sub-nav row on large screens and
 * a MobileNav (fed by megaMenuNavItems) below lg.
 */
export function PublicFrame({
  brand = <Logo size={26} wordmark />,
  menu,
  currentHref,
  signInHref = '/sign-in',
  getStartedHref = '/sign-up',
  footerLinks,
  copyright,
  children,
}: PublicFrameProps) {
  return (
    <StackedLayout
      fullScreen
      width="wide"
      brand={brand}
      actions={
        <>
          <ThemeSwitcher size="sm" className="hidden md:inline-flex" />
          <Button variant="ghost" size="sm" render={<a href={signInHref} />} nativeButton={false}>
            Sign in
          </Button>
          <Button size="sm" render={<a href={getStartedHref} />} nativeButton={false}>
            Get started
          </Button>
          <MobileNav className="lg:hidden" groups={[{ items: megaMenuNavItems(menu) }]} currentHref={currentHref} title="Menu" label="Primary" side="right" />
        </>
      }
      subnav={<MegaMenu items={menu} currentHref={currentHref} label="Primary" className="hidden lg:block" />}
      footer={
        <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
          <span>{copyright}</span>
          <nav aria-label="Footer">
            <ul className="flex flex-wrap gap-x-4 gap-y-1">
              {footerLinks.map((l) => (
                <li key={l.href}>
                  <Link href={l.href} tone="muted" underline="hover">
                    {l.label}
                  </Link>
                </li>
              ))}
            </ul>
          </nav>
        </div>
      }
    >
      {children}
    </StackedLayout>
  );
}

